def generate(seed):
    r = random.Random(seed)
    for _ in range(600):
        A = r.sample("ABCDEFGHJKLMNPRSTUVW", 6)
        pat = [1] * r.randint(2, 3)                       # left end anchored (>=2 books)
        while len(pat) < 32:
            pat += [0] * (1 if r.random() < 0.68 else 2)  # gaps: one slot, or two (decoy)
            pat += [1] * r.choice((1, 1, 2, 2, 3))
        pat += [0] * (1 if r.random() < 0.68 else 2)
        pat += [1] * r.randint(2, 3)                      # right end anchored (>=2 books)
        W = len(pat)
        if not (34 <= W <= 42):
            continue
        g = lambda j: 0 <= j < W and not pat[j]
        cand, iso, far = [], [], []
        for i in range(W):
            if not pat[i]:
                continue
            d = g(i + 1) - g(i - 1)
            if not d:
                if g(i + 1) and g(i - 1):
                    iso.append(i)                         # gaps both sides: nothing tips it
            elif 0 <= i + 2 * d < W and pat[i + 2 * d]:
                cand.append((i, d))                       # something to lean on may be there
            else:
                far.append(i)                             # two-slot gap: nothing within reach
        if not (10 <= len(cand) <= 18) or len(iso) < 2 or len(far) < 2:
            continue
        # Deal the interesting slots so the four named letters own most candidates AND at
        # least one decoy of each kind: a near-miss rule then changes a named tally.
        lab = [None] * W
        cyc = A[:4] + A[:4] + A[4:]
        r.shuffle(cyc)
        idx = list(range(len(cand)))
        r.shuffle(idx)
        for k, ci in enumerate(idx):
            lab[cand[ci][0]] = cyc[k % len(cyc)]
        for pool in (iso, far):
            q = A[:4] + A[4:]
            r.shuffle(q)
            p = list(pool)
            r.shuffle(p)
            for k, i in enumerate(p):
                lab[i] = q[k % 6]
        L = "".join(lab[j] or (r.choice(A) if pat[j] else ".") for j in range(W))
        named = A[:4]
        hmax = r.choice((4, 5, 6))
        H = [r.randint(1, hmax) if pat[j] else 0 for j in range(W)]
        cnt = {}
        for i, d in cand:
            if H[i + 2 * d] > H[i]:
                cnt[L[i]] = cnt.get(L[i], 0) + 1
        tal = [cnt.get(ch, 0) for ch in named]
        if sum(1 for v in tal if v) < 3 or sum(tal) < 4 or max(tal) > 9:
            continue
        r.shuffle(named)
        return L + "/" + " ".join(ch + ":" + str(cnt.get(ch, 0)) for ch in named)
    return "VTL.VA.FL..TF.TS.L..SA.FSL.TL.V..AV..FAT/F:1 A:1 L:2 T:1"

