def draw(L, W, H):
    g = lambda j: 0 <= j < W and L[j] == "."
    M = max(H) + 1
    P = [[" "] * W for _ in range(M)]
    P[M - 1] = list(L)
    for i in range(W):
        h = H[i]
        if h:
            d = g(i + 1) - g(i - 1)
            b = d and 0 <= i + 2 * d < W and H[i + 2 * d] > h
            j = i + d if b else i
            P[M - 1 - h][j] = "_/\\"[b * d]
            for t in range(1, h):
                P[M - 1 - t][j] = L[i]
    return "\n".join(["".join(p) for p in P] + ["=" * W])


def tally(L, W, H):
    g = lambda j: 0 <= j < W and L[j] == "."
    T = {}
    for i in range(W):
        d = g(i + 1) - g(i - 1)
        if H[i] and d and 0 <= i + 2 * d < W and H[i + 2 * d] > H[i]:
            T[L[i]] = T.get(L[i], 0) + 1
    return T


def solve(clue):
    L, K = clue.split("/")
    W = len(L)
    tgt = {p[0]: int(p[2]) for p in K.split()}
    cost = lambda H: sum(abs(tally(L, W, H).get(ch, 0) - v) for ch, v in tgt.items())
    r = random.Random(clue)
    books = [j for j in range(W) if L[j] != "."]
    for _ in range(40):
        hmax = r.choice((3, 4, 5))
        H = [r.randint(1, hmax) if L[j] != "." else 0 for j in range(W)]
        e = cost(H)
        for _ in range(500):
            if not e:
                break
            j = r.choice(books)
            old = H[j]
            H[j] = r.randint(1, hmax)
            e2 = cost(H)
            if e2 <= e:
                e = e2
            else:
                H[j] = old
        if not e:
            return draw(L, W, H)
    return ""

